        of_plan_node_unknown_10 = 0x10;
        of_rm_hunt_begin = 0x88;
        of_rm_fish_begin = 0x98;
        of_rm_lists = 0xA4;
        of_rm_owner = 0x130;
        of_rm_demand = 0x134;
        of_rm_target = 0x150;
        of_rm_timers = 0x16C;
        of_rm_initialized = 0x187;
        of_rm_att_188 = 0x188;
        of_rs_pool_begin = 0x8;
        of_rs_epoch = 0x18;
        of_rs_current = 0x114;
        of_rs_initialized = 0x118;
        of_rs_att_random = 0x11A;
        of_um_requests = 0xC;
        of_um_player = 0x134;
